    },
})

-- plugin { hyprbars { ... } }
-- hyprbars is NOT loaded on this machine (hl.get_loaded_plugins() is empty). Until a plugin is
-- loaded its options do not exist, so an unguarded `plugin = { hyprbars = ... }` is a config
-- error ("unknown config key") and calling hl.plugin.hyprbars.* would abort this file.
-- Hence everything is guarded by `if hl.plugin.hyprbars` (the table the plugin registers).
-- NOTE: pcall(hl.config, ...) is NOT enough: config-key errors are deferred, pcall returns
-- true and verify-config / the error bar still report "unknown config key 'plugin.hyprbars.*'".
-- Hyprland reloads the config automatically after a plugin loads, so this applies then.
if hl.plugin.hyprbars then
    hl.config({
        plugin = {
            hyprbars = {
                -- Honestly idk if it works like css, but well, why not
                bar_text_font = "Google Sans Flex Medium, Rubik, Geist, AR One Sans, Reddit Sans, Inter, Roboto, Ubuntu, Noto Sans, sans-serif",
                bar_height = 30,
                bar_padding = 10,
                bar_button_padding = 5,
                bar_precedence_over_border = true,
                bar_part_of_window = true,

                bar_color = "rgba({{colors.background.default.hex_stripped}}FF)",
                ["col.text"] = "rgba({{colors.on_background.default.hex_stripped}}FF)",
            },
        },
    })
end

-- example buttons (R -> L). fg_color: hyprlang picked black automatically for the light bar; the Lua API requires it explicitly.
-- hyprbars-button = color, size, on-click
-- The on-click commands used `hyprctl dispatch <hyprlang>`; hyprctl dispatch now takes Lua,
-- so they are rewritten (killactive / fullscreen 1 / movetoworkspacesilent special).
if hl.plugin.hyprbars then
    hl.plugin.hyprbars.add_button({ bg_color = "rgb({{colors.on_background.default.hex_stripped}})", fg_color = "rgb(000000)", size = 13, icon = "󰖭",
        action = [[hyprctl dispatch 'hl.dsp.window.close()']] })
    hl.plugin.hyprbars.add_button({ bg_color = "rgb({{colors.on_background.default.hex_stripped}})", fg_color = "rgb(000000)", size = 13, icon = "󰖯",
        action = [[hyprctl dispatch 'hl.dsp.window.fullscreen({ mode = "maximized" })']] })
    hl.plugin.hyprbars.add_button({ bg_color = "rgb({{colors.on_background.default.hex_stripped}})", fg_color = "rgb(000000)", size = 13, icon = "󰖰",
        action = [[hyprctl dispatch 'hl.dsp.window.move({ workspace = "special", follow = false })']] })
end

